#include "component_map_runtime/FlattenCompiler.h"
#include <QCryptographicHash>
#include <QSet>
#include <functional>
#include <algorithm>
using namespace cme::runtime; using namespace cme::runtime::v1;
namespace { void issue(FlattenResult&r,const char*c,const QString&p,const QString&m){r.issues.append({c,p,m});} struct E{QString path,port,def;}; }
FlattenCompiler::FlattenCompiler(FlattenLimits l):m_limits(l){}
FlattenResult FlattenCompiler::compile(const DeploymentGraph& d) const {
 FlattenResult r; if(d.ByteSizeLong()>m_limits.maxSerializedBytes){issue(r,"GRAPH_DEPLOYMENT_SIZE_EXCEEDED",{},"Deployment size exceeds limit.");return r;}
 QMap<QString,const GraphDefinition*> defs; for(const auto& x:d.graph_definitions()){QString k=QString::fromStdString(x.graph_id()+"@"+x.graph_version()); if(defs.contains(k)) issue(r,"DUPLICATE_GRAPH_DEFINITION",k,"Duplicate definition."); else defs[k]=&x;}
 QSet<QString> active,done; std::function<void(const QString&)> cycle=[&](const QString&k){if(active.contains(k)){issue(r,"GRAPH_DEPENDENCY_CYCLE",k,"Dependency cycle.");return;} if(done.contains(k)||!defs.contains(k)) return; active.insert(k); for(const auto& c:defs[k]->components()) if(!c.composite_graph_id().empty()) cycle(QString::fromStdString(c.composite_graph_id()+"@"+c.composite_graph_version())); active.remove(k);done.insert(k);}; for(auto k:defs.keys()) cycle(k); if(!r.issues.isEmpty()) return r;
 GraphDefinition root; root.set_graph_id(d.graph_id()); root.set_graph_version(d.graph_version()); for(const auto&c:d.components())*root.add_components()=c; for(const auto&x:d.routes())*root.add_routes()=x;
 std::function<E(const GraphDefinition&,const QString&,const QString&,const QString&,int)> resolve;
 resolve=[&](const GraphDefinition&g,const QString&prefix,const QString&id,const QString&port,int depth)->E { if(depth>m_limits.maxDepth){issue(r,"GRAPH_DEPTH_EXCEEDED",prefix,"Maximum graph depth exceeded.");return{};} const ComponentInstance *c=nullptr; for(const auto&x:g.components())if(x.instance_id()==id){c=&x;break;} if(!c){issue(r,"BOUNDARY_ENDPOINT_NOT_FOUND",prefix,"Endpoint instance not found.");return{};} if(c->composite_graph_id().empty())return{prefix+"/"+id,port,QString::fromStdString(g.graph_id()+"@"+g.graph_version())}; QString k=QString::fromStdString(c->composite_graph_id()+"@"+c->composite_graph_version()); auto *child=defs.value(k,nullptr); if(!child){issue(r,"GRAPH_DEFINITION_NOT_FOUND",prefix+"/"+id,"Missing definition.");return{};} const ExposedPort *ep=nullptr; for(const auto&x:child->exposed_ports())if(x.port_id()==port){ep=&x;break;} if(!ep){issue(r,"BOUNDARY_PORT_NOT_EXPOSED",prefix+"/"+id+"/"+port,"Port is not exposed.");return{};} return resolve(*child,prefix+"/"+id,QString::fromStdString(ep->internal_instance_id()),QString::fromStdString(ep->internal_port_id()),depth+1); };
 std::function<void(const GraphDefinition&,const QString&,const QString&,int)> expand=[&](const GraphDefinition&g,const QString&prefix,const QString&scope,int depth){if(depth>m_limits.maxDepth){issue(r,"GRAPH_DEPTH_EXCEEDED",prefix,"Maximum graph depth exceeded.");return;} for(const auto&c:g.components()){QString id=QString::fromStdString(c.instance_id()); if(c.composite_graph_id().empty()){FlattenLeaf l{prefix+"/"+id,QString::fromStdString(c.component_type()),scope,QString::fromStdString(g.graph_id()),QString::fromStdString(g.graph_version()),c.state_schema_version(),{}}; for(auto it=c.properties().cbegin();it!=c.properties().cend();++it)l.resolvedProperties.insert(QString::fromStdString(it->first),QString::fromStdString(it->second)); r.plan.leaves.append(l);} else {QString k=QString::fromStdString(c.composite_graph_id()+"@"+c.composite_graph_version());if(!defs.contains(k))issue(r,"GRAPH_DEFINITION_NOT_FOUND",prefix+"/"+id,"Missing definition.");else expand(*defs[k],prefix+"/"+id,k,depth+1);}}
 for(const auto&x:g.routes()){E s=resolve(g,prefix,QString::fromStdString(x.source_instance_id()),QString::fromStdString(x.source_port_id()),depth), t=resolve(g,prefix,QString::fromStdString(x.target_instance_id()),QString::fromStdString(x.target_port_id()),depth); if(s.path.isEmpty()||t.path.isEmpty())continue; r.plan.routes.append({QString::fromStdString(x.connection_id()),s.path,s.port,t.path,t.port,QString::fromStdString(x.message_type()),s.def,t.def,prefix});}};
 expand(root,"root",QString::fromStdString(d.graph_id()+"@"+d.graph_version()),0); if(r.plan.leaves.size()>m_limits.maxLeaves||r.plan.routes.size()>m_limits.maxRoutes)issue(r,"GRAPH_EXPANSION_LIMIT_EXCEEDED",{},"Expansion limit exceeded."); std::sort(r.plan.leaves.begin(),r.plan.leaves.end(),[](auto&a,auto&b){return a.qualifiedPath<b.qualifiedPath;}); std::sort(r.plan.routes.begin(),r.plan.routes.end(),[](auto&a,auto&b){return a.routeId<b.routeId;}); QByteArray serial; for(const auto&x:r.plan.leaves)serial+=x.qualifiedPath.toUtf8()+x.componentType.toUtf8();for(const auto&x:r.plan.routes)serial+=x.routeId.toUtf8()+x.sourceLeafPath.toUtf8()+x.targetLeafPath.toUtf8()+x.sourcePort.toUtf8()+x.targetPort.toUtf8();r.plan.hash=QCryptographicHash::hash(serial,QCryptographicHash::Sha256);r.valid=r.issues.isEmpty();return r;
}
